// One generic algorithm works on any [first, last) range.
template <class It, class T>
It my_find(It first, It last, const T& x) {
    for (; first != last; ++first)      // only ++, !=, * are needed
        if (*first == x) return first;
    return last;                        // "not found" = end iterator
}

int main() {
    vector<int> v = {4, 8, 15, 16, 23, 42};
    list<int> l(v.begin(), v.end());
    int arr[] = {4, 8, 15, 16, 23, 42};

    auto a = my_find(v.begin(), v.end(), 23);
    auto b = my_find(l.begin(), l.end(), 23);
    auto c = my_find(begin(arr), end(arr), 23);
    cout << "vector found: " << *a << " at index " << a - v.begin() << "\n";
    cout << "list found: " << *b << " at index " << distance(l.begin(), b) << "\n";
    cout << "array found: " << *c << " at index " << c - begin(arr) << "\n";

    // Half-open range: a missing value returns last, never dereference it
    auto d = my_find(v.begin(), v.end(), 99);
    cout << "99 found? " << (d != v.end() ? "yes" : "no") << "\n";
    // Time O(N), space O(1)
}

