// Tag dispatch: pick an O(1) or O(k) strategy from the category.
template <class It>
void jump(It& it, int k) {
    using Cat = typename iterator_traits<It>::iterator_category;
    if constexpr (is_base_of_v<random_access_iterator_tag, Cat>) {
        it += k;                                  // O(1)
        cout << "  random access: it += k\n";
    } else {
        for (int i = 0; i < k; i++) ++it;         // O(k)
        cout << "  not random access: " << k << " increments\n";
    }
}

