    auto li = l.begin(); cout << "list\n"; jump(li, 3);
    auto fi = f.begin(); cout << "forward_list\n"; jump(fi, 3);
    cout << "values: " << *vi << " " << *li << " " << *fi << "\n";

    cout << "vector is random access: "
