// Test irreflexivity and asymmetry on sample values.
template <class Cmp>
void check(const string& name, Cmp comp, const vector<int>& xs) {
    bool irreflexive = true, asymmetric = true;
    for (int a : xs) {
        if (comp(a, a)) irreflexive = false;       // comp(a,a) must be false
        for (int b : xs)
            if (comp(a, b) && comp(b, a)) asymmetric = false;
    }
    cout << name << ": irreflexive=" << irreflexive
         << " asymmetric=" << asymmetric << "\n";
}

int main() {
    vector<int> xs = {3, 1, 3, 2, 2};
    cout << "data: 3 1 3 2 2\n";
    check("a < b ", [](int a, int b) { return a < b; }, xs);
    check("a <= b", [](int a, int b) { return a <= b; }, xs);

    // A valid comparator makes equal values "equivalent" in a set
    set<int, less<int>> good(xs.begin(), xs.end());
    cout << "set with < keeps " << good.size() << " keys\n";
    // set with <= would be undefined behaviour, so we only show the check above
    // Cost of the check: O(N^2) time, O(1) space
}

