public class Main {
    // First index with a[i] >= x (n if none). Time O(log N), space O(1).
    static int lowerBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;   // avoids overflow
            if (a[mid] < x) lo = mid + 1;   // answer is right of mid
            else hi = mid;                  // mid might be the answer
        }
        return lo;
    }
    static int upperBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] <= x) lo = mid + 1;  // only change: <=
            else hi = mid;
        }
        return lo;
    }
    public static void main(String[] args) {
        int[] a = {1, 3, 3, 3, 5, 8};
        System.out.println("array: 1 3 3 3 5 8");
        int[] qs = {0, 3, 4, 9};
        for (int x : qs) {
            int lb = lowerBound(a, x), ub = upperBound(a, x);
            System.out.println("x=" + x + " lower=" + lb + " upper=" + ub + " count=" + (ub - lb));
        }
    }
}

