    auto newEnd = remove(v.begin(), v.end(), 2); // moves keepers to the front
    cout << "logical end at index " << newEnd - v.begin() << "\n";
    show("after remove ", v);                    // size unchanged, tail is junk

    v.erase(newEnd, v.end());                    // now the size really changes
    show("after erase  ", v);

    vector<int> d = {3, 1, 3, 2, 1, 3};
    sort(d.begin(), d.end());                    // unique needs equal values adjacent
    d.erase(unique(d.begin(), d.end()), d.end());
    show("sort+unique  ", d);

    vector<int> w = {5, 6, 7, 6, 8};
    size_t n = erase(w, 6);                      // C++20 shortcut
    cout << "std::erase removed " << n << " items\n";
    show("C++20 erase  ", w);
}

#include <bits/stdc++.h>
using namespace std;

// Hand-written version of the four steps. Time O(N) per call.
bool myNext(vector<int>& a) {
    int n = a.size(), i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) i--;      // 1) find pivot
    if (i < 0) { reverse(a.begin(), a.end()); return false; } // 2) last one
    int j = n - 1;
    while (a[j] <= a[i]) j--;                    // 3) smallest bigger value
    swap(a[i], a[j]);
    reverse(a.begin() + i + 1, a.end());         // 4) make suffix minimal
    return true;
}

int main() {
    vector<int> a = {1, 2, 2}, b = a;
    cout << "mine / std::next_permutation:\n";
    do {
        for (int x : a) cout << x;
        cout << " / ";
        for (int x : b) cout << x;
        cout << "\n";
        next_permutation(b.begin(), b.end());
    } while (myNext(a));
    cout << "wrapped back to:";
    for (int x : a) cout << " " << x;
    cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    // Trap 1: int total overflows, long long does not
    vector<int> big = {2000000000, 2000000000, 2000000000};
    long long right = accumulate(big.begin(), big.end(), 0LL);
    cout << "sum with 0LL = " << right << "\n";
    // accumulate(..., 0) would overflow int here (signed overflow is UB)

    // Trap 2: init 0 is an int, so every partial sum is truncated
    vector<double> d = {0.5, 0.5, 0.5, 0.5};
    double wrong = accumulate(d.begin(), d.end(), 0);   // int accumulator
    double ok = accumulate(d.begin(), d.end(), 0.0);
    cout << "doubles 0.5 x4 with 0   = " << wrong << "\n";
    cout << "doubles 0.5 x4 with 0.0 = " << ok << "\n";

    // Same rule for strings: init decides the result type
    vector<string> w = {"a", "b", "c"};
    cout << "joined = " << accumulate(w.begin(), w.end(), string()) << "\n";
    // Time O(N), space O(1)
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int x = 10;
    auto byValue = [x]() { return x; };        // copy made now
    auto byRef = [&x]() { return x; };         // reads the live variable
    x = 20;
    cout << "by value: " << byValue() << ", by reference: " << byRef() << "\n";

    int counter = 0;
    auto inc = [counter]() mutable { return ++counter; }; // mutates its own copy
    cout << "mutable: " << inc() << " " << inc() << ", outer counter = " << counter << "\n";

    // Init-capture moves a unique_ptr into the lambda
    auto p = make_unique<int>(7);
    auto owner = [q = move(p)]() { return *q; };
    cout << "init-capture: " << owner() << ", p is null: " << (p == nullptr) << "\n";

    // Recursive lambda via a generic self parameter (C++14)
    auto fact = [](auto self, int n) -> long long {
        return n <= 1 ? 1 : n * self(self, n - 1);
    };
    cout << "5! = " << fact(fact, 5) << "\n";
    // Dangling bug: returning [&] of a local would point at a dead variable
}

#include <bits/stdc++.h>
using namespace std;

static long long calls = 0;

int cmpC(const void* a, const void* b) {       // qsort: void*, runtime size
    calls++;
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

int main() {
    mt19937 rng(1);
    vector<int> v(20);
    for (int& x : v) x = rng() % 100;
    vector<int> a = v, b = v, c = v;
    cout << "input : ";
    for (int x : v) cout << x << " ";
    cout << "\n";

    sort(a.begin(), a.end(), [](int x, int y) { return x < y; }); // inlined
    qsort(b.data(), b.size(), sizeof(int), cmpC);                 // indirect calls
    function<bool(int,int)> f = [](int x, int y) { return x < y; };
    sort(c.begin(), c.end(), f);                                  // indirect again

    cout << "sorted: ";
    for (int x : a) cout << x << " ";
    cout << "\nall three agree: " << (a == b && b == c) << "\n";
    cout << "qsort made " << calls << " indirect compare calls\n";
    // Same O(N log N); the lambda version is just faster per comparison
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> data = {7, 2, 9, 4, 4, 1, 8, 4};
    vector<int> sorted = data;
    sort(sorted.begin(), sorted.end());          // build once: O(N log N)
    set<int> s(data.begin(), data.end());        // loses duplicates anyway

    cout << "sorted:";
    for (int x : sorted) cout << " " << x;
    cout << "\n";

    for (int x : {0, 4, 5, 9}) {
        // index of first element > x equals how many values are <= x
        int cnt = upper_bound(sorted.begin(), sorted.end(), x) - sorted.begin();
        cout << "count <= " << x << " = " << cnt << "\n";
    }

    // set finds the position in O(log N) but the rank needs a walk
    auto it = s.upper_bound(5);
    cout << "set rank of 5 via distance (O(N)) = " << distance(s.begin(), it)
         << " distinct keys <= 5\n";
    // Each query on the sorted vector: O(log N) time, O(1) space
}

#include <bits/stdc++.h>
