#include <bits/stdc++.h>
using namespace std;

// Fast: count distinct values with sort + unique. O(N log N)
int fast(vector<int> v) {
    sort(v.begin(), v.end());
    return unique(v.begin(), v.end()) - v.begin();
}
// Brute force: obviously correct, O(N^2)
int brute(const vector<int>& v) {
    int c = 0;
    for (size_t i = 0; i < v.size(); i++) {
        bool seen = false;
        for (size_t j = 0; j < i; j++) if (v[j] == v[i]) seen = true;
        if (!seen) c++;
    }
    return c;
}

int main() {
    mt19937 rng(12345);                           // fixed seed = reproducible
    int bad = 0;
    for (int iter = 0; iter < 1000; iter++) {
        int n = rng() % 8 + 1;                    // small N finds bugs fast
        vector<int> v(n);
        for (int& x : v) x = (int)(rng() % 5) - 2; // small range -> many duplicates
        if (fast(v) != brute(v)) {
            bad++;
            cout << "MISMATCH on:";
            for (int x : v) cout << " " << x;
            cout << "\n";
            break;
        }
    }
    cout << "1000 random tests, mismatches: " << bad << "\n";
}
